import pytest

from bedrock_protocol import v1001, v2168, v2225

versions = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.AutomationClientConnect{ServerURI: "ws://localhost:8000/ws"}
URI = bytes.fromhex("1677733a2f2f6c6f63616c686f73743a383030302f7773")

# generated by gophertunnel b8bd735:
# packet.AutomationClientConnect{ServerURI: ""}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# packet.AutomationClientConnect{ServerURI: strings.Repeat("a", 200)}
LONG = bytes.fromhex(
    "c801616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "6161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "6161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "6161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "6161"
)

GOLDENS = [
    *[
        pytest.param(
            version.AutomationClientConnectPacket(
                web_socket_data=version.WebSocketPacketData(ip="ws://localhost:8000/ws")
            ),
            URI,
            id=f"{version.__name__.rpartition('.')[2]}-uri",
        )
        for version in versions
    ],
    *[
        pytest.param(
            version.AutomationClientConnectPacket(web_socket_data=version.WebSocketPacketData(ip="")),
            EMPTY,
            id=f"{version.__name__.rpartition('.')[2]}-empty-uri",
        )
        for version in versions
    ],
    *[
        pytest.param(
            version.AutomationClientConnectPacket(web_socket_data=version.WebSocketPacketData(ip="a" * 200)),
            LONG,
            id=f"{version.__name__.rpartition('.')[2]}-uri-past-127-bytes",
        )
        for version in versions
    ],
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_automation_client_connect_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_automation_client_connect_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
